#!/bin/bash

# Common Functions.
printVersion() {
    echo '0.18.0-alpha.6'
}
RCM_VERSION=`printVersion`

source=$RCM_LIB/functions/common/echo.sh; [ -f "$source" ] && source "$source" || exit 1

# Parse arguments. Generated by parse-options.sh
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help) help=1; shift ;;
        --version) version=1; shift ;;
        --[^-]*) shift ;;
        add|list|execute|helper|init)
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
        *) _new_arguments+=("$1"); shift ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments

# Command.
if [ -n "$1" ];then
    command=
    case "$1" in
        add) command="$1"; shift ;;
        list) command="$1"; shift ;;
        execute) command="$1"; shift ;;
        helper) command="$1"; shift ;;
        init) command="$1"; shift ;;
    esac
    if [ -z "$command" ];then
        error Command unknown: '`'"$1"'`'.; x
    fi
fi

case "$command" in
    add)
        _new_arguments=()
        while [[ $# -gt 0 ]]; do
            case "$1" in
                --help) help=1; shift ;;
                --command=*) add_command="${1#*=}"; shift ;;
                --command) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then add_command="$2"; shift; fi; shift ;;
                --fast) fast=1; shift ;;
                --interface=*) interface="${1#*=}"; shift ;;
                --interface) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then interface="$2"; shift; fi; shift ;;
                --name=*) name="${1#*=}"; shift ;;
                --name) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then name="$2"; shift; fi; shift ;;
                --table=*) table="${1#*=}"; shift ;;
                --table) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then table="$2"; shift; fi; shift ;;
                --table-temporary=*) table_temporary="${1#*=}"; shift ;;
                --table-temporary) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then table_temporary="$2"; shift; fi; shift ;;
                --temporary) temporary=1; shift ;;
                --version=*) add_version="${1#*=}"; shift ;;
                --version) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then add_version="$2"; shift; fi; shift ;;
                --[^-]*) shift ;;
                *) _new_arguments+=("$1"); shift ;;
            esac
        done
        set -- "${_new_arguments[@]}"
        unset _new_arguments
        ;;
    list)
        _new_arguments=()
        while [[ $# -gt 0 ]]; do
            case "$1" in
                --help) help=1; shift ;;
                --fast) fast=1; shift ;;
                --interface=*) interface="${1#*=}"; shift ;;
                --interface) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then interface="$2"; shift; fi; shift ;;
                --table=*) table="${1#*=}"; shift ;;
                --table) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then table="$2"; shift; fi; shift ;;
                --table-temporary=*) table_temporary="${1#*=}"; shift ;;
                --table-temporary) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then table_temporary="$2"; shift; fi; shift ;;
                --[^-]*) shift ;;
                *) _new_arguments+=("$1"); shift ;;
            esac
        done
        set -- "${_new_arguments[@]}"
        unset _new_arguments
        ;;
    execute)
        _new_arguments=()
        while [[ $# -gt 0 ]]; do
            case "$1" in
                --help) help=1; shift ;;
                --fast) fast=1; shift ;;
                --ignore-fail-on-empty-name) ignore_fail_on_empty_name=1; shift ;;
                --interface=*) interface="${1#*=}"; shift ;;
                --interface) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then interface="$2"; shift; fi; shift ;;
                --method=*) method="${1#*=}"; shift ;;
                --method) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then method="$2"; shift; fi; shift ;;
                --name=*) name="${1#*=}"; shift ;;
                --name) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then name="$2"; shift; fi; shift ;;
                --output-file=*) output_file="${1#*=}"; shift ;;
                --output-file) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then output_file="$2"; shift; fi; shift ;;
                --table=*) table="${1#*=}"; shift ;;
                --table) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then table="$2"; shift; fi; shift ;;
                --table-temporary=*) table_temporary="${1#*=}"; shift ;;
                --table-temporary) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then table_temporary="$2"; shift; fi; shift ;;
                --[^-]*) shift ;;
                *) _new_arguments+=("$1"); shift ;;
            esac
        done
        set -- "${_new_arguments[@]}"
        unset _new_arguments
        ;;
    init)
        _new_arguments=()
        while [[ $# -gt 0 ]]; do
            case "$1" in
                --help) help=1; shift ;;
                --fast) fast=1; shift ;;
                --interface=*) interface="${1#*=}"; shift ;;
                --interface) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then interface="$2"; shift; fi; shift ;;
                --table=*) table="${1#*=}"; shift ;;
                --table) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then table="$2"; shift; fi; shift ;;
                --[^-]*) shift ;;
                *) _new_arguments+=("$1"); shift ;;
            esac
        done
        set -- "${_new_arguments[@]}"
        unset _new_arguments
esac

# Define variables and constants.

# If not set in argument, try load from environment.
[ -z "$fast" ] && fast="$RCM_FAST"

# If set in environment, set to variable.
[ -n "$RCM_VERBOSE" ] && verbose="$RCM_VERBOSE"
[ -n "$RCM_RESOLVE_DEPENDENCIES" ] && resolve_dependencies="$RCM_RESOLVE_DEPENDENCIES"
[ -n "$RCM_TABLE_DOWNLOADS" ] && table_downloads="$RCM_TABLE_DOWNLOADS"
[ -n "$RCM_TABLE_DEPENDENCIES" ] && table_dependencies="$RCM_TABLE_DEPENDENCIES"
[ -n "$RCM_TABLE_COMMAND_RESOLVED" ] && table_command_resolved="$RCM_TABLE_COMMAND_RESOLVED"
[ -n "$RCM_VERSION" ] && rcm_version="$RCM_VERSION"

# Boolean default to TRUE.
[ -z "$fast" ] && fast=1; [ "$fast" == 0 ] && fast=
[ -z "$resolve_dependencies" ] && resolve_dependencies=1; [ "$resolve_dependencies" == 0 ] && resolve_dependencies=

# Verbosity.
quiet=; loud=; louder=; debug=;
[[ -z "$verbose" || "$verbose" -lt 1 ]] && quiet=1 || quiet=
[[ "$verbose" -gt 0 ]] && loud=1
[[ "$verbose" -gt 1 ]] && loud=1 && louder=1
[[ "$verbose" -gt 2 ]] && loud=1 && louder=1 && debug=1

# Define variables and constants.

# Functions. Help and Version.
usage() {
    title Rapid Construct Massive
    _ 'Plugin System'; _.
    _ 'Version '; yellow `printVersion`; _.
    _.
cat << EOF
Usage: rcm-plugin <command> [options]

Available commands: add, list, execute, init.

Options for command init:
   --interface *
        Set the plugin category. Value available from command: rcm-plugin(helper interface-available), or other.

Options for command add:
   --interface *
        Set the plugin category. Value available from command: rcm-plugin(helper interface-available), or other.
   --name *
        Set the plugin name.
   --command *
        Command of plugin to execute.
   --version *
        Command version.
   --table
        File table to store plugin information.
        Default value is \$HOME/.config/rcm/rcm.plugin.table.[--interface]
        Prepopulate value from variable RCM_PLUGIN_[--interface^^]_TABLE.
   --temporary ^
        Set as temporary additional.
   --table-temporary
        File table to temporary store plugin information.
        Value available from command: rcm-plugin(helper temporary-suggestion [--temporary] [--interface]), or others.
        Prepopulate value from variable RCM_PLUGIN_[--interface^^]_TABLE_TEMPORARY.

Options for command list:
   --interface *
        Set the plugin category. Value available from command: rcm-plugin(helper interface-available), or other.
   --table
        File table to store plugin information.
        Default value is \$HOME/.config/rcm/rcm.plugin.table.[--interface]"
        Prepopulate value from variable RCM_PLUGIN_[--interface^^]_TABLE.
   --table-temporary
        File table to temporary store plugin information.
        Value available from command: rcm-plugin(helper temporary-suggestion 1 [--interface]), or others.
        Prepopulate value from variable RCM_PLUGIN_[--interface^^]_TABLE_TEMPORARY.

Options for command execute:
   --interface *
        Set the plugin category. Value available from command: rcm-plugin(helper interface-available), or other.
   --table
        File table to store plugin information.
        Default value is \$HOME/.config/rcm/rcm.plugin.table.[--interface]"
        Prepopulate value from variable RCM_PLUGIN_[--interface^^]_TABLE.
   --table-temporary
        File table to temporary store plugin information.
        Value available from command: rcm-plugin(helper temporary-suggestion 1 [--interface]), or others.
        Prepopulate value from variable RCM_PLUGIN_[--interface^^]_TABLE_TEMPORARY.
   --name *
        Set the plugin name.
        Value available from command: rcm-plugin(helper list [--interface] [--table] [--table-temporary]), or others.
   --interface *
        Set the interface.

Global Options:
   --fast
        No delay every subtask.
   --version
        Print version of this script.
   --help
        Show this help.

Environment Variables:
   BINARY_DIRECTORY
        Default to $BINARY_DIRECTORY

RCM Config:
   --no-timer
   --no-confirmation
EOF
}

# Help and Version.
[ -n "$help" ] && { usage; exit 1; }
[ -n "$version" ] && { printVersion; exit 1; }

command-add() {
    local command version

    title rcm-plugin::add
    ____

    [ -n "$louder" ] && chapter Variable dump
    if [ -z "$interface" ];then
        error "Argument --interface required."; x
    fi
    [ -n "$louder" ] && code 'interface="'$interface'"'
    # Interface, Name, dan Method digabung menjadi function
    # dengan string dash.
    # Oleh karena itu jangan ada dash pada ketiga entity tersebut.
    if [[ "$interface" =~ [^a-z_] ]];then
        error "Argument --interface is not valid."; x
    fi
    if [ -z "$name" ];then
        error "Argument --name required."; x
    fi
    [ -n "$louder" ] && code 'name="'$name'"'
    if [[ "$name" =~ [^a-z_] ]];then
        error "Argument --name is not valid."; x
    fi
    if [ -z "$add_command" ];then
        error "Argument --command required."; x
    fi
    command="$add_command"
    [ -n "$louder" ] && code 'command="'$command'"'
    if [ -z "$add_version" ];then
        error "Argument --version required."; x
    fi
    version="$add_version"
    [ -n "$louder" ] && code 'version="'$version'"'
    [ -n "$louder" ] && code 'temporary="'$temporary'"'
    [ -n "$louder" ] && code 'table="'$table'"'
    [ -n "$louder" ] && code 'table_temporary="'$table_temporary'"'
    # If not set in argument, try load from environment.
    local interface_uppercase=${interface^^}
    local parameter_table="RCM_PLUGIN_${interface_uppercase}_TABLE"
    parameter_table=$(echo "$parameter_table"| sed 's|[^A-Z]|_|g' | sed -E 's|_+|_|')
    parameter_table="${!parameter_table}"
    local parameter_table_temporary="RCM_PLUGIN_${interface_uppercase}_TABLE_TEMPORARY"
    parameter_table_temporary=$(echo "$parameter_table_temporary"| sed 's|[^A-Z]|_|g' | sed -E 's|_+|_|')
    parameter_table_temporary="${!parameter_table_temporary}"
    [ -z "$table" ] && table="$parameter_table"
    [ -z "$table_temporary" ] && table_temporary="$parameter_table_temporary"
    [ -n "$louder" ] && code 'table="'$table'"'
    [ -n "$louder" ] && code 'table_temporary="'$table_temporary'"'
    # Use default value.
    if [ -z "$table" ];then
        table="${HOME}/.config/rcm/rcm.plugin.table.${interface}"
    fi
    if [ -n "$temporary" ];then
        if [ -z "$table_temporary" ];then
            mkdir -p "${HOME}/.cache/rcm"
            table_temporary=$(mktemp -p ${HOME}/.cache/rcm -t rcm.plugin.table.${interface}.XXXXXX)
        fi
    fi
    [ -n "$louder" ] && code 'table="'$table'"'
    [ -n "$louder" ] && code 'table_temporary="'$table_temporary'"'
    [ -n "$louder" ] && ____

    chapter Add to table.
    local table_lookup=
    if [ -n "$temporary" ];then
        table_lookup="$table_temporary"
    else
        table_lookup="$table"
    fi
    local line
    if [ -f "$table_lookup" ];then
        line=$(grep -n -F "${name} ${command} ${version}" "$table_lookup")
    fi
    if [ -z "$line" ];then
        local table_dirname=$(dirname "$table_lookup")
        mkdir -p "$table_dirname"
        echo "${name} ${command} ${version}" >> "$table_lookup"
        success Added.
    else
        __ Already added.
    fi
    ____

    if [ -n "$temporary" ];then
        echo "RCM_PLUGIN_${interface_uppercase}_TABLE_TEMPORARY=${table_temporary}"
    else
        echo "RCM_PLUGIN_${interface_uppercase}_TABLE=${table}"
    fi
}
command-list() {
    if [ -z "$interface" ];then
        error "Argument --interface required."; x
    fi
    if [[ "$interface" =~ [^a-z_] ]];then
        error "Argument --interface is not valid."; x
    fi

    # If not set in argument, try load from environment.
    local interface_uppercase=${interface^^}
    local parameter_table="RCM_PLUGIN_${interface_uppercase}_TABLE"
    parameter_table=$(echo "$parameter_table"| sed 's|[^A-Z]|_|g' | sed -E 's|_+|_|')
    parameter_table="${!parameter_table}"
    local parameter_table_temporary="RCM_PLUGIN_${interface_uppercase}_TABLE_TEMPORARY"
    parameter_table_temporary=$(echo "$parameter_table_temporary"| sed 's|[^A-Z]|_|g' | sed -E 's|_+|_|')
    parameter_table_temporary="${!parameter_table_temporary}"
    [ -z "$table" ] && table="$parameter_table"
    [ -z "$table_temporary" ] && table_temporary="$parameter_table_temporary"
    # Use default value.
    if [ -z "$table" ];then
        table="${HOME}/.config/rcm/rcm.plugin.table.${interface}"
    fi
    local contents=
    if [ -f "$table_temporary" ] ;then
        contents+=$'\n'
        contents+=$(cut -d' ' -f1 < "$table_temporary")
    fi
    if [ -f "$table" ] ;then
        # Filter duplikat.
        contents+=$'\n'
        contents+=$(cut -d' ' -f1 <"$table" | sort -u)
    fi
    echo "$contents" | sed '/^[[:space:]]*$/d'
}
command-execute() {
    is_command_resolved() {
        if [ -z "$resolve_dependencies" ];then
            return 0
        fi
        if grep -q -F "$rcm_extension" <<< "$table_command_resolved";then
            return 0
        fi
        return 1
    }

    title rcm-plugin::execute
    ____

    local find replace contents command

    [ -n "$louder" ] && chapter Variable dump
    if [ -z "$interface" ];then
        error "Argument --interface required."; x
    fi
    [ -n "$louder" ] && code 'interface="'$interface'"'
    if [[ "$interface" =~ [^a-z_] ]];then
        error "Argument --interface is not valid."; x
    fi
    [ "$name" == - ] && name=
    if [ -z "$name" ];then
        if [ -n "$ignore_fail_on_empty_name" ];then
            return 0
        fi
        error "Argument --name required."; x
    fi
    [ -n "$louder" ] && code 'name="'$name'"'
    if [[ "$name" =~ [^a-z_] ]];then
        error "Argument --name is not valid."; x
    fi
    if [ -z "$method" ];then
        error "Argument --method required."; x
    fi
    [ -n "$louder" ] && code 'method="'$method'"'
    if [[ "$method" =~ [^a-z_] ]];then
        error "Argument --method is not valid."; x
    fi
    [ -n "$louder" ] && code 'output_file="'$output_file'"'
    # If not set in argument, try load from environment.
    local interface_uppercase=${interface^^}
    local parameter_table="RCM_PLUGIN_${interface_uppercase}_TABLE"
    parameter_table=$(echo "$parameter_table"| sed 's|[^A-Z]|_|g' | sed -E 's|_+|_|')
    parameter_table="${!parameter_table}"
    local parameter_table_temporary="RCM_PLUGIN_${interface_uppercase}_TABLE_TEMPORARY"
    parameter_table_temporary=$(echo "$parameter_table_temporary"| sed 's|[^A-Z]|_|g' | sed -E 's|_+|_|')
    parameter_table_temporary="${!parameter_table_temporary}"
    [ -z "$table" ] && table="$parameter_table"
    [ -z "$table_temporary" ] && table_temporary="$parameter_table_temporary"
    [ -n "$louder" ] && code 'table="'$table'"'
    [ -n "$louder" ] && code 'table_temporary="'$table_temporary'"'
    # Use default value.
    if [ -z "$table" ];then
        table="${HOME}/.config/rcm/rcm.plugin.table.${interface}"
    fi
    [ -n "$louder" ] && code 'table="'$table'"'
    [ -n "$louder" ] && code 'table_temporary="'$table_temporary'"'
    # Translate variable.
    find='$HOME'; replace="$HOME"
    [ -n "$table" ] && table="${table/"$find"/"$replace"}"
    [ -n "$table_temporary" ] && table_temporary="${table_temporary/"$find"/"$replace"}"
    [ -n "$louder" ] && code 'table="'$table'"'
    [ -n "$louder" ] && code 'table_temporary="'$table_temporary'"'
    if [ -f "$table_temporary" ] ;then
        contents+=$'\n'
        contents+=$(<"$table_temporary")
    fi
    if [ -f "$table" ] ;then
        contents+=$'\n'
        contents+=$(<"$table")
    fi
    if [ -n "$contents" ];then
        command=$(echo "$contents" | grep ^"$name" | cut -d' ' -f2 | tail -1)
        command_version=$(echo "$contents" | grep ^"$name" | cut -d' ' -f3 | tail -1)
    fi
    if [ -z "$command" ];then
        error "The Command of \`plugin::${interface}-${name}\` is not defined in table."; x
    fi
    if ! command -v "$command" > /dev/null;then
        error Command not found: '`'"$command"'`'.; x
    fi

    [ -n "$louder" ] && ____

    rcm_extension="$command"

    if ! is_command_resolved;then

        chapter Resolve dependency for command '`'$command'`'.
        ____

        # Boolean export as 0 or 1. Must not leave empty string.
        [ -n "$fast" ] && RCM_FAST=1 || RCM_FAST=0
        # Other variable, export as is.
        RCM_TABLE_DOWNLOADS="$table_downloads"
        RCM_TABLE_DEPENDENCIES="$table_dependencies"
        RCM_VERSION="$rcm_version"
        RCM_VERBOSE="$verbose"

        INDENT+="$RCM_INDENT" \
        BINARY_DIRECTORY="$BINARY_DIRECTORY" \
        RCM_FAST="$RCM_FAST" \
        RCM_VERBOSE="$RCM_VERBOSE" \
        RCM_TABLE_DOWNLOADS="$RCM_TABLE_DOWNLOADS" \
        RCM_TABLE_DEPENDENCIES="$RCM_TABLE_DEPENDENCIES" \
        RCM_VERSION="$RCM_VERSION" \
        rcm-resolve "${command}:${command_version}" \
            ; [ ! $? -eq 0 ] && x
    fi

    chapter Execute "${command}::plugin-${interface}-${name}-${method}()"
    code "${command} plugin ${interface} ${name} ${method}"
    ____

    [ -n "$fast" ] && RCM_FAST=1 || RCM_FAST=0
    export RCM_FAST="$RCM_FAST"
    if [ -z "$output_file" ];then
        RCM_ENVIRONMENT_VARIABLES= RCM_PROMPT_CHAIN= INDENT+="    " ${command} plugin ${interface} ${name} ${method} \
            ; [ ! $? -eq 0 ] && x
    else
        RCM_ENVIRONMENT_VARIABLES= RCM_PROMPT_CHAIN= INDENT+="    " ${command} plugin ${interface} ${name} ${method} \
            > "$output_file" \
            ; [ ! $? -eq 0 ] && { rm "$output_file"; x; }
    fi
}
command-init() {

    title rcm-plugin::init
    ____

    [ -n "$louder" ] && chapter Variable dump
    if [ -z "$interface" ];then
        error "Argument --interface required."; x
    fi
    [ -n "$louder" ] && code 'interface="'$interface'"'
    if [[ "$interface" =~ [^a-z_] ]];then
        error "Argument --interface is not valid."; x
    fi
    local interface_uppercase=${interface^^}

    # If not set in argument, try load from environment.
    local parameter_table="RCM_PLUGIN_${interface_uppercase}_TABLE"
    parameter_table=$(echo "$parameter_table"| sed 's|[^A-Z]|_|g' | sed -E 's|_+|_|')
    parameter_table="${!parameter_table}"
    [ -z "$table" ] && table="$parameter_table"
    # Use default value.
    if [ -z "$table" ];then
        table="${HOME}/.config/rcm/rcm.plugin.table.${interface}"
    fi
    [ -n "$louder" ] && ____

    echo "RCM_PLUGIN_${interface_uppercase}_TABLE=${table}"
}
command-helper() {
    local which=$1; shift
    if [ "$which" == do-nothing ];then
        return
    fi
    if [ -n "$which" ];then
        if [[ $(type -t "helper-${which}") == function ]];then
            helper-${which} "$@"
            exit 0
        else
            error Helper unknown: '`'"$command"'`'.; x
        fi
    fi
}
helper-interface-available() {
    if [ -d "${HOME}/.config/rcm" ];then
        cd "${HOME}/.config/rcm"
        ls -1 rcm.plugin.table.* | grep -o -P 'rcm\.plugin\.table\.\K(\S+)'
    fi
}
helper-temporary-suggestion() {
    local is_temporary=$1
    if [ "$is_temporary" == 0 ];then
        exit 1
    fi
    local category=$2
    echo "\$HOME/.cache/rcm/rcm.plugin.table.$category.${RANDOM}${RANDOM}"
}
helper-list() {
    local category=$1
    local table=$2; [ "$table" == - ] && table=
    local table_temporary=$3; [ "$table_temporary" == - ] && table_temporary=
    command-list
}

# Execute command.
if [ -n "$command" ];then
    if [[ $(type -t "command-${command}") == function ]];then
        command-${command} "$@"
        exit 0
    else
        error The function of command '`'"$command"'`' has not yet defined.; x
    fi
fi

usage >/dev/null | head -3
_ Try; blue ' 'rcm-plugin; magenta ' '--help; _, ' 'for more information.; _.

